    out = [row[:] for row in grid]

    markers = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                markers.setdefault(v, []).append((r, c))

    # 1 makes a short rightward elbow.
    for r, c in markers.get(1, []):
        for d in (1, 2):
            if c + d < w:
                out[r][c + d] = 5
        if r > 0 and c + 4 < w:
            out[r - 1][c + 4] = 1

    # 2 makes a five-cell horizontal bar.
    for r, c in markers.get(2, []):
        for d, value in ((-4, 2), (-3, 5), (-2, 5), (-1, 5)):
            if 0 <= c + d < w:
                out[r][c + d] = value

    # 3 extends three cells down.
    for r, c in markers.get(3, []):
        for d, value in ((1, 5), (2, 5), (3, 3)):
            if r + d < h:
                out[r + d][c] = value

    # 6 extends upward to a fixed six-cell endpoint.
    for r, c in markers.get(6, []):
        for d in range(1, 7):
            if r - d >= 0:
                out[r - d][c] = 6 if d == 6 else 5

    # A crossing between the 2 bar and a vertical 3/6 line becomes 4,
    # with a diagonal trail continuing down-left.
    for r, c in markers.get(2, []):
        for x in range(max(0, c - 3), c):
            if any(x == vc and vr <= r for vr, vc in markers.get(3, []) + markers.get(6, [])):
                out[r][x] = 4
                rr, cc = r + 1, x - 1
                while rr < h and cc >= 0:
                    out[rr][cc] = 4
                    rr += 1
                    cc -= 1

    return out
